"""Prompt model."""

from dataclasses import dataclass

from sqlalchemy import BigInteger, ForeignKey, Integer, String, Text, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from bot.db.base import Base, TimestampMixin

# BigInteger for PostgreSQL, INTEGER for SQLite (need for AUTOINCREMENT)
BigIntPK = BigInteger().with_variant(Integer, "sqlite")


class Prompt(TimestampMixin, Base):
    """User-defined prompt templates."""

    __tablename__ = "prompts"
    __table_args__ = (UniqueConstraint("user_id", "prompt_name"),)

    # Internal surrogate primary key, generated by the database.
    id: Mapped[int] = mapped_column(BigIntPK, primary_key=True, autoincrement=True)

    prompt_name: Mapped[str] = mapped_column(String(128))
    prompt_text: Mapped[str] = mapped_column(Text)
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), index=True)

    def __repr__(self) -> str:
        return f"Prompt(id={self.id}, prompt_name={self.prompt_name!r})"


@dataclass(frozen=True, kw_only=True, slots=True)
class PromptCreateData:
    user_id: int
    prompt_name: str
    prompt_text: str
